import "./ListGroup.css"
import { EventListener } from "@lottiefiles/dotlottie-react";

export default function ListGroup() {

  const items = ['Auswahl1', 'Auswahl2', 'Auswahl3'];
  const myList = document.querySelector('.listItems')

  return (
    <ul className="GroupList">
      {items.map((item, index) => 
        <li 
        className="listItems" 
        key={item} 
        onClick={(myList) => item.addEveListener}>
            {item}
        </li>
      )}
    </ul>
  );
}
